func numSquares(n int) int {
    dp := make([]int, n+1)
    for i := 1; i <= n; i++ {
        dp[i] = i // 最坏情况全用 1
        for j := 1; j*j <= i; j++ {
            dp[i] = min(dp[i], dp[i-j*j]+1)
        }
    }
    return dp[n]
}

func numSquares(n int) int {
    visited := make([]bool, n+1)
    queue := []int{n}
    visited[n] = true
    steps := 0
    for len(queue) > 0 {
        steps++
        size := len(queue)
        for i := 0; i < size; i++ {
            cur := queue[i]
            for j := 1; j*j <= cur; j++ {
                next := cur - j*j
                if next == 0 {
                    return steps
                }
                if !visited[next] {
                    visited[next] = true
                    queue = append(queue, next)
                }
            }
        }
        queue = queue[size:]
    }
    return n
}
